const linhas = await csv('uber-elegibilidade.csv');
const achado = linhas.find((linha) => chave(linha.documento) === chave(documento));

if (!achado) {
  return { encontrado: false };
}

const mesesUber = Number(achado.mesesUber);
const corridas = Number(achado.corridas);
const rating = Number(achado.rating);
const status = achado.status;

return {
  encontrado: true,
  nome: achado.nome,
  cidade: achado.cidade,
  uf: achado.uf,
  mesesUber,
  corridas,
  status,
  rating,
  categoria: achado.categoria,
  ultimaCorrida: achado.ultimaCorrida,
  veiculoProprio: achado.veiculoProprio === 'sim',
  elegivelMinimo: status === 'ativo' && mesesUber >= 6 && corridas >= 500 && rating >= 4.7,
};
